<?php

/** Helpers globaux utilisés par les vues admin. */

function e(null|string|int|float $value): string
{
    return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
}

function csrf_token(): string
{
    if (empty($_SESSION['csrf_token'])) {
        $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
    }
    return $_SESSION['csrf_token'];
}

function csrf_field(): string
{
    return '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
}

/** Message flash one-shot (succès / erreur) stocké en session. */
function flash(?string $type = null, ?string $message = null): ?array
{
    if ($type !== null) {
        $_SESSION['flash'] = ['type' => $type, 'message' => $message];
        return null;
    }
    $data = $_SESSION['flash'] ?? null;
    unset($_SESSION['flash']);
    return $data;
}

function format_datetime(?string $value): string
{
    if (!$value) {
        return '—';
    }
    $ts = strtotime($value);
    return $ts ? date('d/m/Y H\hi', $ts) : $value;
}

function format_price(null|int|float|string $amount, string $currency = 'F CFA'): string
{
    if ($amount === null || $amount === '') {
        return '—';
    }
    return number_format((float) $amount, 0, ',', ' ') . ' ' . $currency;
}

/**
 * Pagination compacte (chevrons + numéros fenêtrés + état actif), même rendu
 * que la liste des inscriptions. $query : filtres à conserver (sans 'page').
 */
function pagination(int $page, int $pages, string $baseUrl, array $query = []): string
{
    if ($pages <= 1) {
        return '';
    }
    $query = array_filter($query, static fn ($v) => $v !== null && $v !== '');
    $url = static fn (int $p): string => e($baseUrl . '?' . http_build_query(array_merge($query, ['page' => $p])));

    $window = 2;
    $shown = [];
    for ($p = 1; $p <= $pages; $p++) {
        if ($p === 1 || $p === $pages || abs($p - $page) <= $window) {
            $shown[] = $p;
        }
    }

    $html = '<nav class="mt-6 flex flex-wrap items-center justify-center gap-1.5" aria-label="Pagination">';
    $html .= '<a class="page-btn ' . ($page <= 1 ? 'page-btn-disabled' : '') . '" href="' . $url(max(1, $page - 1))
        . '" title="Page précédente">' . icon('chevron-left', 'h-4 w-4') . '</a>';
    $prev = 0;
    foreach ($shown as $p) {
        if ($p - $prev > 1) {
            $html .= '<span class="px-1 text-slate-400">…</span>';
        }
        $html .= $p === $page
            ? '<span class="page-btn page-btn-active" aria-current="page">' . $p . '</span>'
            : '<a class="page-btn" href="' . $url($p) . '">' . $p . '</a>';
        $prev = $p;
    }
    $html .= '<a class="page-btn ' . ($page >= $pages ? 'page-btn-disabled' : '') . '" href="' . $url(min($pages, $page + 1))
        . '" title="Page suivante">' . icon('chevron-right', 'h-4 w-4') . '</a>';
    return $html . '</nav>';
}

